import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-09-17","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-09-17","date":"2025-09-17T00:00:00.000Z","updated":"2025-09-19T00:00:00.000Z","tags":["Ceph","RGW","KMIP","SSE-S3","生命周期管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-09-17.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-09-17.md","lastUpdated":1780460162000}'),r={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-09-17.md"};function l(n,e,p,s,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要-ceph-rgw-重构会议-2025-09-17" tabindex="-1">会议纪要 - Ceph RGW 重构会议 2025-09-17 <a class="header-anchor" href="#会议纪要-ceph-rgw-重构会议-2025-09-17" aria-label="Permalink to &quot;会议纪要 - Ceph RGW 重构会议 2025-09-17&quot;">​</a></h3><p>本次会议主要讨论了以下几个关键议题：</p><ol><li><p><strong>KMIP 后端支持 SSE-S3 的设计讨论</strong>：</p><ul><li>设计目标：参考 Vault Transit 后端模式，实现 KMIP 后端对 SSE-S3 的支持，采用 KEK 和 DEK 分离模型。</li><li>代码贡献策略：优先在 Ceph 的 <code>libkmip</code> fork 中开发，并推动上游合并。</li><li>测试计划：转向 Go 实现的 KMIP 服务测试，替代 <code>pykmip</code>，并恢复 CI 测试覆盖。</li></ul></li><li><p><strong>RGW 生命周期处理问题分析及解决方案</strong>：</p><ul><li>问题现象：Bucket 处理被错误跳过，因 <code>already_run_today</code> 逻辑缺陷。</li><li>根因分析：Shard 锁复用问题和 <code>is_expired</code> 检查误用。</li><li>解决方案：优化时间判断逻辑，处理锁竞争，分离 shard 锁与 bucket 状态更新锁。</li></ul></li><li><p><strong>DBStore 后端未来规划</strong>：</p><ul><li>现状：新测试用例普遍不支持 DBStore，开发重心转向 POSIX 后端。</li><li>共识：DBStore 已达成概念验证目标，若无特殊需求可逐步弃用。</li></ul></li></ol><h3 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h3><ul><li><strong>KMIP 性能优化</strong>：计划引入 Per-Bucket Key 减少密钥操作开销。</li><li><strong>测试改进</strong>：增强生命周期处理的并发测试覆盖。</li></ul><h3 id="下一步行动计划" tabindex="-1">下一步行动计划 <a class="header-anchor" href="#下一步行动计划" aria-label="Permalink to &quot;下一步行动计划&quot;">​</a></h3><p>| 任务 | 负责人 | 时间节点 | |-|-|| | 提交 KMIP Encrypt/Decrypt PR | 提案人 | 两周内 | | 修复 LC <code>is_expired</code> 逻辑 | Kunal | 本周 | | 优化 <code>already_run_today</code> 逻辑 | Casey | 下周 | | 评估 Go KMIP 测试方案 | 全体相关成员 | 持续跟进 |</p><p>本次会议针对 RGW 的重构进行了深入讨论，明确了后续的开发方向和行动计划。</p>',8)])])}const u=t(r,[["render",l]]);export{h as __pageData,u as default};
